type View='home'|'workbench'|'tasks'|'environments'|'knowledge'|'execution'|'methods'|'access'|'audit';
type Role='engineer'|'viewer'|'expert'|'security'|'maintainer';
const icons:Record<string,string>={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',task:'<path d="M9 5h11M9 12h11M9 19h11M3 5l1 1 2-2M3 12l1 1 2-2M3 19l1 1 2-2"/>',network:'<rect x="8" y="2" width="8" height="6" rx="1.5"/><rect x="2" y="16" width="7" height="6" rx="1.5"/><rect x="15" y="16" width="7" height="6" rx="1.5"/><path d="M12 8v4M5.5 16v-4h13v4"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',terminal:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m6 9 3 3-3 3M12 15h5"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-2-16-4 20"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',audit:'<path d="M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9l-7-7Z"/><path d="M14 2v7h7M7 13h10M7 17h7"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',play:'<path d="m7 4 14 8-14 8V4Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',check:'<path d="m5 12 4 4L19 6"/>',server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M16 6.5h2M16 17.5h2"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18Z"/>',cloud:'<path d="M6 18h12a4 4 0 0 0 1-8 7 7 0 0 0-13-1 4.5 4.5 0 0 0 0 9Z"/>',file:'<path d="M14 2H5v20h14V7l-5-5Z"/><path d="M14 2v5h5M8 12h8M8 16h6"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H3l2.5-5a8.5 8.5 0 1 1 15-3.5Z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'};
const icon=(name:string,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]??icons.grid}</svg>`;
const esc=(value:string)=>value.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const roleNames:Record<Role,string>={engineer:'研发工程师 · 林珊',viewer:'观察员 · 陈远',expert:'产品专家 · 周宁',security:'安全管理员 · 许禾',maintainer:'平台运维 · 吴森'};
const roles:Record<Role,string[]>={engineer:['read','run','control','create'],viewer:['read'],expert:['read','run','control','create','publish'],security:['policy','audit'],maintainer:['health','maintenance','audit']};
const nav:[View,string,string,string?][]=[['home','产品空间','grid'],['workbench','任务空间','chat'],['tasks','任务中心','task','3'],['environments','环境与拓扑','network'],['knowledge','资料与记录','book'],['execution','设备与执行','terminal'],['methods','方法库','code'],['access','人员与权限','shield'],['audit','操作记录','audit']];
const state={view:'home' as View,role:'engineer' as Role,tab:'path',phase:3,running:false,paused:false,complete:false,title:'修复升级后的连接异常，完成回归测试',taskId:'TASK-0248',chatOpen:false,extraMessages:[] as {role:string,text:string}[],audits:[] as string[],taskFilter:'',taskStatus:'all',product:'ADC 应用交付',missionKind:'develop',workspaceTab:'process',startDraft:'',chatDraft:''};
const can=(action:string)=>roles[state.role].includes(action);
const tag=(text:string,type='gray')=>`<span class="tag ${type}">${text}</span>`;
const btn=(action:string,text:string,primary=false,symbol='')=>`<button class="btn${primary?' primary':''}" data-action="${action}">${symbol?icon(symbol,13):''}${text}</button>`;
let runTimer:ReturnType<typeof setTimeout>|undefined;
function notice(message:string){document.querySelector('.toast')?.remove();const node=document.createElement('div');node.className='toast';node.setAttribute('role','status');node.textContent=message;document.body.append(node);setTimeout(()=>node.remove(),3500);}
function audit(message:string){state.audits.unshift(`${new Date().toLocaleTimeString('zh-CN',{hour12:false})}  ${roleNames[state.role]}  ${message}`);}
function allowed(action:string){if(can(action))return true;audit(`拒绝 ${action}：当前角色没有该权限`);notice('当前角色没有此操作权限。此处仅演示前端权限交互。');return false;}
function render(){const name=nav.find(n=>n[0]===state.view)![1];document.querySelector('#app')!.innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('shield',20)}</span><div class="brand-text">infosec<small>AI WORKSPACE</small></div></div><div class="workspace"><div class="square">IS</div><div>产品工程团队<span>研发项目⌄</span></div></div><div class="nav-label">工作空间</div>${nav.slice(0,4).map(navItem).join('')}<div class="nav-label">平台能力</div>${nav.slice(4,7).map(navItem).join('')}<div class="nav-label">管理</div>${nav.slice(7).map(navItem).join('')}<div class="nav-footer"><span class="dot"></span>本地交互原型<br>仅供页面演示</div></aside><main class="main" id="main-content"><header class="topbar"><div class="breadcrumb">${icon('grid',13)}<span>研发项目</span><span>/</span><strong>${name}</strong></div><div class="top-actions"><button class="global-search" data-action="search">${icon('search',12)} 搜索 <kbd>⌘ K</kbd></button><button class="environment" data-action="demo-info">界面演示</button><select class="role-select" id="role" aria-label="切换演示人员角色">${Object.entries(roleNames).map(([id,title])=>`<option value="${id}" ${state.role===id?'selected':''}>${title}</option>`).join('')}</select><button class="btn small chat-toggle" data-action="chat-toggle" aria-label="打开原生 Web 对话">${icon('chat',13)}</button></div></header><div class="content">${content()}</div></main>${state.view==='home'||state.view==='workbench'?'':chat()}</div>`;}
function navItem([id,title,symbol,count]:[View,string,string,string?]){return`<button class="nav-button ${state.view===id?'active':''}" data-view="${id}" aria-label="${title}" aria-current="${state.view===id?'page':'false'}">${icon(symbol)}<span class="nav-text">${title}</span>${count?`<span class="count">${demoTasks.length}</span>`:''}</button>`;}
function pageTitle(title:string,subtitle:string,action=''){return`<div class="page-title"><div><div class="eyebrow">PRODUCT OPERATIONS / DEMO</div><h1>${title}</h1><div class="subtle">${subtitle}</div></div>${action}</div>`;}
const missionKinds:Record<string,{label:string,goal:string,icon:string,steps:[string,string][]}>={
knowledge:{label:'查资料',goal:'比较两版产品的能力与限制，给出有依据的结论',icon:'book',steps:[['固定产品与资料版本','规格、手册、许可与已知限制'],['查询相关资料与代码','保留出处，说明来源之间的冲突'],['解释差异和适用条件','LLM 分析，脚本核对引用与明确字段'],['交付有据答案','结论、原文、条件与仍缺资料分别呈现']]},
review:{label:'评审方案',goal:'评审这项需求，分析影响并补齐验收条件',icon:'file',steps:[['澄清目标与约束','关联需求、产品版本和使用环境'],['对照规格与现有实现','资料、代码和已知问题一起分析'],['评审方案与测试覆盖','保留分歧、候选方案和适用条件'],['交付评审与验收要求','让开发、测试与产品人员使用同一份依据']]},
develop:{label:'开发修复',goal:'修复升级后的连接异常，完成回归测试',icon:'code',steps:[['查产品资料与代码','固定规格、代码修订与已知行为'],['建立复现与测试环境','保存输入、拓扑、配置和独立预期'],['分析原因并验证假设','脚本记录事实，LLM 对跨模块原因判定'],['形成修复与影响说明','代码或配置变更关联原问题和消费者'],['执行回归并核对结果','分别检查测试结果、现场效果与遗留'],['交付修改与完整依据','补丁、报告、输入输出及未验证范围']]},
test:{label:'执行测试',goal:'为这项功能准备网络环境，评审用例并执行验证',icon:'network',steps:[['固定规格与验证目标','先说明独立预期和适用条件'],['评审并补齐测试用例','覆盖正常、故障、未知与恢复'],['准备拓扑和观察点','产品与网络知识共同构建环境'],['执行测试并分析结果','脚本判明确规则，LLM 解释其余内容'],['交付覆盖与证据','测试资料、实际结果与缺项一起交付']]},
operate:{label:'配置设备',goal:'完成授权的配置变更，核对配置与实际业务效果',icon:'terminal',steps:[['核对身份、版本与授权','目标、环境、允许动作和控制者明确'],['准备变更与前置检查','记录配置原件与回退条件'],['执行并展示现场','同一 SSH 或浏览器会话，可观察和接管'],['回读配置与业务验证','执行成功与业务通过分别记录'],['交付变更前后记录','核对残留、未知结果和清理']]},
release:{label:'准备发布',goal:'检查发布候选，验证升级与回退并整理交付',icon:'server',steps:[['固定候选版本和范围','制品、变更与支持版本绑定'],['核对构建与回归记录','检查必要结果，保留缺项'],['验证升级和回退','专用环境与允许动作需明确'],['准备准备发布交付','制品、兼容说明、证据和遗留分别呈现']]},
diagnosis:{label:'网络排障',goal:'定位业务入口 502，并验证转发路径',icon:'search',steps:[['固定业务与网络条件','客户端、产品、后端与观察点明确'],['复现并取得独立观察','管理、业务和后端结果分别保留'],['分析并区分候选原因','对照产品行为与跨层网络证据'],['验证修复与业务结果','修复动作不代替实际效果检查'],['交付调查与回归记录','完整输入输出及未验证范围']]}}
function inferKind(goal:string){if(/修复|代码|开发|bug/i.test(goal))return'develop';if(/评审|需求|设计/.test(goal))return'review';if(/发布|升级|回退/.test(goal))return'release';if(/配置|操作|设备|web/i.test(goal))return'operate';if(/测试|环境|用例|验证/.test(goal))return'test';if(/答疑|比较|限制|资料/.test(goal))return'knowledge';return'develop';}
function launchMission(goal:string,kind?:string,isNew=true){if(!allowed(isNew?'create':'read'))return;if(runTimer)clearTimeout(runTimer);state.running=false;state.paused=false;state.complete=false;state.phase=isNew?0:2;state.extraMessages=[];state.startDraft='';state.chatDraft='';state.title=goal;state.missionKind=kind??inferKind(goal);if(!isNew){const previous=demoTasks.find(t=>t.title===goal);if(previous)state.taskId=previous.id;}if(isNew){state.taskId=`TASK-${String(Math.max(...demoTasks.map(t=>Number(t.id.split('-')[1])))+1).padStart(4,'0')}`;demoTasks.unshift({id:state.taskId,title:goal,scope:`${state.product} / 演示项目`,status:'调查中',type:'green'});}state.workspaceTab='process';state.view='workbench';audit(`${isNew?'创建':'打开'} ${state.missionKind} 演示`);render();}
function taskExplanation(){const messages:Record<string,string>={develop:'我先检查版本变更和连接处理代码，再准备复现用例。修复后运行回归，交付修改内容和测试结果。',review:'我会对照产品规格和现有实现检查方案，再补充需要验证的场景。有分歧的地方会单独列出。',test:'先检查用例是否覆盖要求，再准备拓扑和流量。执行后把实际结果与预期逐项比较。',operate:'我先核对设备、版本和操作权限。变更前保留配置，变更后回读并检查业务访问。',release:'我会检查制品和回归记录，再整理兼容性、升级和回退结果。缺少的记录会单独列出。',knowledge:'我会查找相关资料，比较版本和适用条件。答案会附上出处，资料冲突也会说明。',diagnosis:'先分别检查客户端、设备和后端，再结合配置与请求记录缩小范围。找到原因后，再验证修复效果。'};return messages[state.missionKind]??messages.develop;}
function taskDiagram(){const steps=missionKinds[state.missionKind]?.steps??missionKinds.develop.steps;const items=steps.slice(0,6);const count=items.length;const cols=count<=4?2:3;const w=cols===2?288:184;const x=(i:number)=>cols===2?(i<2?24+i*310:24+(3-i)*310):(i<3?24+i*212:24+(5-i)*212);const y=(i:number)=>i<cols?23:126;const lines=items.slice(0,-1).map((_,i)=>{const x1=x(i),x2=x(i+1),y1=y(i),y2=y(i+1);const d=y1===y2?`M${x1<x2?x1+w:x1},${y1+31} H${x1<x2?x2:x2+w}`:`M${x1+w/2},${y1+64} V${y2}`;return`<path class="diagram-line" d="${d}" marker-end="url(#task-arrow)"/>`;}).join('');const labels:Record<string,string[]>={develop:['查资料和代码','复现问题','分析原因','修复','回归测试','交付'],review:['明确需求','检查方案','补充测试要求','交付评审'],knowledge:['确认版本','查资料','比较和解释','给出答案'],test:['确认要求','评审用例','准备环境','执行测试','交付结果'],operate:['核对设备','准备变更','执行操作','检查效果','交付记录'],release:['确认版本','检查回归','验证升级回退','准备交付'],diagnosis:['确认业务','采集现象','分析原因','验证修复','交付结果']};return`<div class="task-state-heading"><span>任务步骤</span><span>点击查看记录</span></div><div class="diagram-wrap"><svg class="task-diagram" viewBox="0 0 660 218" role="group" aria-label="任务步骤图"><defs><marker id="task-arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M1 1l5 3-5 3" fill="none" stroke="#cbcbd5" stroke-width="1.2"/></marker></defs>${lines}${items.map(([title],i)=>`<g class="diagram-step" data-action="diagram-step" data-step="${i}" role="button" tabindex="0" aria-label="${labels[state.missionKind]?.[i]??title}"><rect class="diagram-node ${i===state.phase&&!state.complete?'current':''}" x="${x(i)}" y="${y(i)}" width="${w}" height="64" rx="6"/><circle class="diagram-dot ${i<state.phase?'done':''}" cx="${x(i)+15}" cy="${y(i)+21}" r="3"/><text class="diagram-label" x="${x(i)+27}" y="${y(i)+25}">${labels[state.missionKind]?.[i]??title}</text><text class="diagram-sub" x="${x(i)+27}" y="${y(i)+46}">${i<state.phase?'已有记录':i===state.phase?'当前步骤':'等待前一步'}</text></g>`).join('')}</svg></div>`;}
function openStep(index:number){if(!allowed('read'))return;if(index===3&&state.missionKind==='develop'){state.workspaceTab='changes';render();return;}if(index===missionKinds[state.missionKind].steps.length-1){state.workspaceTab='delivery';render();return;}openDetail(index===2?'model':index===1?'script':'run');}
function navigate(view:View){state.view=view;history.pushState({view},'',`#/${view}`);render();}
function showDemoInfo(){closeOverlay();rememberFocus();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-action="close-overlay"></div><div class="modal" role="dialog" aria-modal="true" aria-label="演示说明"><div class="drawer-title"><h2>演示说明</h2><button class="close" data-action="close-overlay" aria-label="关闭演示说明">×</button></div><div class="subtle">这版用于评审页面和交互。<br><br>产品、任务、回答和操作都是样例，没有连接真实设备或模型。角色切换只演示权限提示，真实平台需要后端鉴权。输入只保存在当前页面，刷新后恢复初始状态。</div></div>`);(document.querySelector('.modal .close') as HTMLButtonElement).focus();}
function openSearch(){closeOverlay();rememberFocus();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-action="close-overlay"></div><div class="modal" role="dialog" aria-modal="true" aria-label="搜索"><div class="drawer-title"><h2>搜索</h2><button class="close" data-action="close-overlay" aria-label="关闭搜索">×</button></div><input id="global-query" placeholder="搜索任务或页面" aria-label="搜索任务或页面"><div id="global-results"></div></div>`);(document.querySelector('#global-query') as HTMLInputElement).focus();updateSearch('');}
function updateSearch(query:string){const allowedItems=nav.filter(item=>can('read')||['access','audit','execution'].includes(item[0]));const pages=allowedItems.filter(item=>item[1].includes(query)).map(([id,title,symbol])=>`<button class="workstream-row" data-view="${id}" data-action="close-overlay">${icon(symbol,15)}<span class="workstream-text">${title}</span>${icon('arrow',12)}</button>`);const tasks=can('read')?demoTasks.filter(t=>(t.title+t.id).includes(query)).map(t=>`<button class="workstream-row" data-action="search-task" data-task="${t.id}"><span class="workstream-text"><strong>${esc(t.title)}</strong><small>${t.id}</small></span>${icon('arrow',12)}</button>`):[];document.querySelector('#global-results')!.innerHTML=[...tasks,...pages].join('')||'<div class="empty">没有找到结果</div>';}

function productHome(){return`<section class="product-home"><div class="home-intro"><div><div class="eyebrow">INFOSEC / PRODUCT WORKSPACE</div><h1>工作台</h1><p>选一个产品，告诉平台你要做什么。</p></div><div class="home-day"><b>产品工程团队</b><br>Web 工作台</div></div><div class="goal-surface"><div class="goal-label">${icon('spark',16)} 开始一项工作</div><textarea id="start-goal" aria-label="输入产品工作目标" placeholder="例如：查明连接中断的原因，修复后完成回归测试。">${esc(state.startDraft)}</textarea><div class="goal-bottom"><div class="goal-context"><select id="home-product" aria-label="选择演示产品">${['ADC 应用交付','WAF 应用安全','NGFW 网络安全'].map(name=>`<option ${name===state.product?'selected':''}>${name}</option>`).join('')}</select><span>${icon('lock',10)} 当前项目</span><span>资料、代码和环境</span></div><button class="goal-submit" data-action="launch-goal">开始工作 ${icon('arrow',15)}</button></div></div><div class="workflow-presets">${Object.entries(missionKinds).filter(([key])=>key!=='diagnosis').map(([kind,item])=>`<button class="preset" data-action="preset" data-kind="${kind}" data-goal="${esc(item.goal)}">${icon(item.icon,20)}<strong>${item.label}</strong><small>${({knowledge:'附上资料出处',review:'从目标到验收',develop:'从复现到回归',test:'从环境到结果',operate:'可见的实际操作',release:'检查版本与制品'} as any)[kind]}</small></button>`).join('')}</div><div class="section-title"><div><h2>产品</h2><p>资料、版本、代码、环境与方法，在同一个产品上下文中关联。</p></div><button data-view="knowledge">查看资料 ${icon('arrow',13)}</button></div><div class="product-spaces">${[['ADC 应用交付','负载均衡 / 应用交付控制器','shield','连接处理、业务转发、TLS 与高可用。','规格 · 架构','代码 · 缺陷','测试 · 环境'],['WAF 应用安全','Web 应用防护 / 安全策略','globe','检测规则、应用协议、误报与防护行为。','策略 · 规则','应用 · 流量','版本 · 验证'],['NGFW 网络安全','下一代防火墙 / 网络访问控制','network','网络路径、访问策略、会话与协议处理。','拓扑 · 路径','策略 · 会话','发布 · 维护']].map(([name,sub,symbol,desc,...assets])=>`<button class="product-space ${state.product===name?'selected':''}" data-action="choose-product" data-product="${name}"><div class="product-space-top"><span class="product-symbol">${icon(symbol,22)}</span><div><h3>${name}</h3><small>${sub}</small></div></div><div class="product-space-state">${state.product===name?'当前产品':'选择产品'} ${icon('arrow',11)}</div></button>`).join('')}</div><div class="section-title"><div><h2>最近的任务</h2><p>目标、执行与依据保留在任务中，换入口后也能继续。</p></div><button data-view="tasks">全部任务 ${icon('arrow',13)}</button></div><div class="workstream-list">${[['develop','修复升级后的连接异常，完成回归测试','ADC · 4.3.x','分析与复现','65'],['review','评审应用防护方案','WAF','等待复核','35'],['test','准备会话保持的测试环境和用例','ADC','准备环境','25'],['release','检查发布版本的兼容性和回退记录','NGFW','检查交付','80']].map(([kind,title,sub,phase,progress])=>`<button class="workstream-row" data-action="open-mission" data-product="${sub.startsWith('WAF')?'WAF 应用安全':sub.startsWith('NGFW')?'NGFW 网络安全':'ADC 应用交付'}" data-kind="${kind}" data-goal="${esc(title)}"><span class="workstream-icon">${icon(missionKinds[kind].icon,17)}</span><span class="workstream-text"><strong>${title}</strong><small>${sub}</small></span><span class="workstream-phase"><span class="phase-bar"><i style="width:${progress}%"></i></span>${phase}</span>${tag('可继续','green')}${icon('arrow',14)}</button>`).join('')}</div><div class="home-bottom"><span>${icon('check',12)} 脚本事实与 LLM 判断分别披露</span><span>${icon('shield',12)} 按人员、项目、环境与资源限定权限</span><span>仅为界面演示，未连接真实产品</span></div></section>`;}
function nativeWorkspace(){const method=missionKinds[state.missionKind]??missionKinds.develop;const phase=Math.min(state.phase,method.steps.length);return`<section class="mission-workspace"><div class="mission-header"><div><div class="home-product-title"><button class="text-link" data-view="home">产品空间</button> / ${esc(state.product)} / ${method.label}</div><h1>${esc(state.title)}</h1><div class="mission-meta">${tag(state.taskId)}${tag(state.complete?'已完成（模拟）':state.paused?'已暂停':state.running?'进行中':'演示','green')}<span>使用当前产品资料</span><span>测试环境</span></div></div>${state.running?btn('pause','暂停',false,'pause'):btn('run',state.paused?'继续执行':state.complete?'重新运行':'继续执行',true,'play')}</div><div class="mission-layout"><div class="mission-core"><div class="tabs">${[['process','对话'],['changes','变更'],['execution','执行'],['io','输入输出'],['delivery','交付']].map(([id,label])=>`<button class="tab ${state.workspaceTab===id?'active':''}" data-workspace-tab="${id}">${label}</button>`).join('')}</div>${state.workspaceTab==='process'?`<div class="mission-stream"><div class="mission-author"><span class="badge-avatar" style="background:#edf1f3">林</span>用户目标</div><div class="mission-request">${esc(state.title)}</div><div class="mission-author"><span class="ai-mark">${icon('spark',12)}</span>平台助手 ${tag('')}</div><p>${taskExplanation()}</p>${taskDiagram()}<button class="citation" data-detail="model">${icon('file',13)} 查看判断依据 ${icon('arrow',12)}</button>${state.extraMessages.map(m=>`<div style="margin-top:24px">${m.role==='user'?`<div class="mission-request">${esc(m.text)}</div>`:`<div class="mission-author"><span class="ai-mark">${icon('spark',12)}</span>平台助手 · 模拟</div><p>${esc(m.text)}</p>`}</div>`).join('')}</div><div class="mission-composer"><textarea id="chat-input" aria-label="输入任务目标或问题" placeholder="补充信息，或告诉平台下一步怎么做…">${esc(state.chatDraft)}</textarea><div class="composer-footer"><span>${icon('file',12)} 当前任务</span><button class="send" data-action="send" aria-label="发送消息">${icon('arrow',15)}</button></div></div>`:workspaceOutput()}</div><aside class="mission-context"><section class="context-card"><h2>${icon('book',14)} 相关资料</h2>${[['产品',state.product],['版本','演示版本'],['资料','规格与已知问题'],['代码','当前修订'],['环境','测试环境']].map(([k,v])=>`<div class="context-item"><span>${k}</span><b>${v}</b></div>`).join('')}<button class="text-link" data-detail="run">查看详情 ${icon('arrow',11)}</button></section><section class="context-card"><h2>${icon('check',14)} 交付内容</h2>${['修改内容','检查结果','原始记录','未完成项'].map(text=>`<div class="delivery-item">${icon('file',12)} ${text}</div>`).join('')}</section><section class="context-card"><h2>${icon('shield',14)} 执行现场</h2><div class="context-help">查看终端或浏览器，必要时接管操作。</div><div style="margin-top:14px">${btn('takeover','接管',false,'eye')}</div></section></aside></div></section>`;}
function workspaceOutput(){if(state.workspaceTab==='io')return`<div class="mission-output">${evidenceView()}</div>`;if(state.workspaceTab==='execution')return`<div class="mission-output"><div class="section-title"><h2>实际执行与观察</h2>${tag('演示')}</div>${state.missionKind==='diagnosis'||state.missionKind==='operate'?`${terminal()}<div class="spacer"></div>${webPreview()}`:`<div class="terminal"><div class="terminal-title"><span>隔离工作区 / 执行记录</span><span>合成内容</span></div><div class="command">task ${state.taskId} / ${state.missionKind}</div><div>product: ${esc(state.product)}</div><div>input: specification + code revision + test environment</div><div class="dim">${state.complete?'Simulated task finished. No real effects were produced.':'Pending verified execution. This prototype does not run tools.'}</div></div><div class="info-banner">按任务需要关联构建、测试、SSH 或浏览器现场，不为所有工作强制安排设备连接。</div>`}</div>`;if(state.workspaceTab==='changes')return`<div class="mission-output"><div class="section-title"><h2>变更与影响</h2>${tag('未执行')}</div><div class="mission-empty">修改的代码、配置和文档会列在这里。<br>这次演示没有修改真实代码。</div><div class="spacer"></div><button class="btn" data-detail="method">查看方法与适用条件</button></div>`;return`<div class="mission-output"><div class="section-title"><h2>交付与验收</h2>${tag(state.complete?'演示已准备':'待完成',state.complete?'green':'amber')}</div><div class="mission-empty">${state.complete?'演示已完成，可以展开输入输出与模拟交付记录。':'工作推进后，产物、核验、支持范围与缺项会在这里逐项核对。'}<br>本页不会把交互动画作为真实交付证据。</div><div style="margin-top:20px">${btn('download','下载演示记录',false,'file')}</div></div>`;}

function content(){if(['home','workbench','tasks','environments','knowledge','methods'].includes(state.view)&&!can('read'))return`${pageTitle(nav.find(n=>n[0]===state.view)![1],'人员角色与业务权限分离')}<div class="panel"><div class="wide-message">${icon('lock',22)}<h3>你没有此项目的访问权限</h3>你可以查看${state.role==='security'?'权限策略与操作记录':'设备与执行的健康状态与维护入口'}。系统管理角色不会自动获得资料、任务内容或设备操作权限。</div></div><div class="info-banner">这是前端权限演示。真实平台必须由后端执行鉴权，页面隐藏不能构成安全边界。</div>`;if(state.view==='home')return productHome();if(state.view==='workbench')return nativeWorkspace();if(state.view==='tasks')return tasks();if(state.view==='environments')return environments();if(state.view==='knowledge')return knowledge();if(state.view==='execution')return execution();if(state.view==='methods')return methods();if(state.view==='access')return access();return audits();}
function workbench(){return`${pageTitle('任务工作台','围绕一个目标，持续调查、验证与交付。',btn('new-task','新建任务',false,'plus'))}<div class="summary"><div class="metric"><div class="metric-label">进行中的任务</div><strong>${state.complete?'00':'01'}</strong><small>当前项目</small></div><div class="metric"><div class="metric-label">等待复核</div><strong>01</strong><small>方法版本评审</small></div><div class="metric"><div class="metric-label">已有交付</div><strong>${state.complete?'02':'01'}</strong><small>合成演示结果</small></div></div><section class="panel"><div class="task-head"><div class="task-meta">${tag(state.taskId)}${tag(state.complete?'已完成（模拟）':state.paused?'演示已暂停':state.running?'进行中':'演示调查中',state.paused?'amber':'green')}${tag('隔离网络','blue')}<span style="margin-left:auto;font-size:9px;color:#9ca7ac">刚刚更新</span></div><h2 class="task-title">${esc(state.title)}</h2><div class="subtle">目标：恢复客户端 → 虚拟服务 → 后端的访问，并保留变更前后的独立证据。</div><div class="task-foot"><span><span class="badge-avatar">林</span> ${roleNames[state.role].split(' · ')[1]}</span><span>负载均衡 / 合成设备 v1</span><span>LAB-LB-01</span><span class="last">${icon('clock',11)} 运行记录 DEMO-RUN-0248</span></div></div><div class="phase-strip">${['准备环境','复现问题','采集证据','分析原因','验证修复','交付结果'].map((text,i)=>`<div class="phase ${i<state.phase?'done':i===state.phase?'current':''}"><span class="phase-number">${i<state.phase?'✓':i+1}</span>${text}</div>`).join('')}</div></section><section class="panel"><div class="tabs">${[['path','业务路径'],['terminal','SSH 现场'],['web','Web 现场'],['evidence','输入输出']].map(([id,label])=>`<button class="tab ${state.tab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div><div class="tab-content">${state.tab==='path'?businessPath():state.tab==='terminal'?terminal():state.tab==='web'?webPreview():evidenceView()}</div><div class="panel-footer"><span>${icon('eye',12)} 可追查观察、模型判断与模拟操作</span><div class="run-controls">${state.running?btn('pause','暂停',false,'pause'):btn('run',state.paused?'继续执行':state.complete?'重新运行':'运行诊断演示',true,'play')}</div></div></section><div class="lower-grid"><section class="panel"><div class="panel-heading"><h2>${icon('task',14)} 执行记录</h2><small>合成事件</small></div>${eventRows()}<div class="panel-footer"><span>操作结果与业务结果分别记录</span><button data-detail="run" class="btn small">查看完整记录 ${icon('arrow',11)}</button></div></section><section class="panel"><div class="panel-heading"><h2>${icon('spark',14)} 原因分析</h2>${tag('模拟 LLM 判断','blue')}</div><div class="hypothesis"><div class="hyp-top"><span>转发目标配置与预期不一致</span>${tag(state.complete?'模拟验证一致':'待验证',state.complete?'green':'amber')}</div><p>管理可达、业务 502、后端直连正常。仍需核对转发配置与请求是否到达后端。</p></div><div class="hypothesis"><div class="hyp-top"><span>后端服务本身异常</span>${tag('当前证据不支持')}</div><p>合成直连探测返回 200，尚不能据此排除所有时间段与请求条件。</p></div><div class="panel-footer"><span>假设与可核验事实分开</span><button class="btn small" data-detail="model">查看输入输出 ${icon('arrow',11)}</button></div></section></div><div class="info-banner">${icon('shield',12)} 交互原型：所有数据、回答、执行和鉴权结果均为演示。没有连接设备或真实模型，前端权限展示不代表后端安全实现。</div>`;}
function businessPath(){return`<div class="path-head"><strong>请求路径 <span style="color:#9aa8af;margin-left:8px">HTTP / 合成拓扑</span></strong><span>4 个观察点 · 配置快照 r12</span></div><div class="path-flow">${[['client','globe','客户端','请求发起','good'],['network','network','测试网络','二 / 三层','good'],['device','shield','LAB-LB-01',state.complete?'模拟恢复 200':'业务入口 502',state.complete?'good':'warn'],['backend','server','后端服务','直连探测 200','good']].map(([id,symbol,title,sub,type],i)=>`${i?`<div class="path-link ${i===3&&!state.complete?'bad':''}"></div>`:''}<button class="path-node ${type}" data-detail="${id}"><span class="node-icon">${icon(symbol,23)}</span><strong>${title}</strong><small>${sub}</small></button>`).join('')}</div><div class="path-callout">${icon(state.complete?'check':'search',14)}<div><strong>${state.complete?'演示中的修复前后对比已完成。':'管理页面可访问，不代表业务转发正常。'}</strong><br>${state.complete?'配置回读与业务探测分别记录；这是模拟输出，尚无真实设备结论。':'下一步：核对虚拟服务指向的目标，与后端独立探测结果交叉比较。'}</div></div>`;}
function terminal(){return`<div class="terminal"><div class="terminal-title"><span>${icon('terminal',12)} LAB-LB-01 / 演示 SSH 会话</span><span>只读观察 · 合成输出</span></div><div class="command">lab-device# show identity</div><div>identity: lab-device-01 &nbsp; version: fixture-v1</div><div class="command">lab-device# show virtual-service demo-http</div><div>backend: synthetic-unconfigured</div><div class="command">client$ probe demo-http</div><div class="${state.complete?'command':'error'}">HTTP ${state.complete?'200 — simulated restored':'502 — synthetic forwarding failure'}</div><div class="dim">原始字节与显示内容分别留存 · 此处为交互样例</div></div><div class="info-banner">${can('control')?'当前工程角色可在测试域请求控制；接管仅模拟，不会连接真实终端。':'当前角色只有查看权限，无终端输入或接管权限。'} <button class="btn small" data-action="takeover">接管</button></div>`;}
function webPreview(){return`<div class="web-preview"><div class="browserbar"><span class="browserdot"></span><span class="browserdot"></span><span class="browserdot"></span><span class="browser-url">${icon('lock',9)} lab-device.demo / virtual-services</span><span>演示页面</span></div><div class="synthetic-web"><div class="device-menu">概览<br>虚拟服务<br>后端资源<br>健康检查<br>系统状态</div><div class="device-content"><h3>demo-http 虚拟服务</h3><div class="form-line"><span>所属设备</span><b>LAB-LB-01</b></div><div class="form-line"><span>转发目标</span><b>${state.complete?'demo-backend':'synthetic-unconfigured'}</b></div><div class="form-line"><span>业务探测</span>${tag(state.complete?'200 / 模拟':'502 / 模拟',state.complete?'green':'amber')}</div><div style="margin-top:13px">${btn('takeover','接管此演示会话',false,'eye')}</div></div></div></div><div class="info-banner">成熟产品中这里关联 D 持有的同一真实浏览器会话；本 demo 用合成页面示意，不是独立登录页或实时浏览器流。</div>`;}
function evidenceView(){return`<div class="table-wrap"><table><thead><tr><th>记录</th><th>类型与范围</th><th>状态</th><th></th></tr></thead><tbody>${[['script','明确规则的核验记录','脚本 / 已固定的输入与规则','合成事实'],['model','任务分析的完整输入输出','模拟 LLM / 明确证据缺口','待核验判断'],['run','任务与操作记录','任务、输入版本、执行与重试','演示记录']].map(([id,title,sub,status])=>`<tr><td><span class="cell-main">${title}</span><span class="cell-sub">DEMO-RUN-0248 · 当前输入版本</span></td><td>${sub}</td><td>${tag(status,id==='model'?'blue':'green')}</td><td><button class="btn small" data-detail="${id}">展开</button></td></tr>`).join('')}</tbody></table></div>`;}
function eventRows(){const rows=[['check','固定输入与环境','资料 rev.3 · 方法 1.2 · 合成拓扑','10:24:03'],['terminal','取得独立观察','管理 200 / 业务 502 / 后端 200','10:24:07'],['spark','形成候选原因','模拟分析，待配置回读核验','10:24:11']];if(state.phase>=4)rows.push(['code','比较配置与预期','演示：转发目标与预期不一致','刚刚']);if(state.phase>=5)rows.push(['check','模拟修复与回归','配置回读、业务探测分别记录','刚刚']);return rows.map(([symbol,title,sub,time])=>`<div class="list-row"><span class="row-icon">${icon(symbol,14)}</span><div class="row-main"><strong>${title}</strong><small>${sub}</small></div><span class="timestamp">${time}</span></div>`).join('');}
function chat(){const permitted=can('read');return`<aside class="chat ${state.chatOpen?'open':''}"><div class="chat-header"><div class="chat-title"><span class="ai-mark">${icon('spark',13)}</span>任务协作</div><button class="chat-toggle" data-action="chat-toggle" aria-label="关闭对话">×</button>${tag('Web 对话')}</div><div class="chat-subheader"><span>${state.taskId} · ${permitted?'当前任务上下文':'无业务内容权限'}</span>${tag('模拟回答')}</div><div class="chat-messages">${permitted?`<div class="message"><div class="message-role"><span class="badge-avatar" style="background:#e6eef1">林</span>林珊</div><div class="user-message">测试业务入口一直返回 502，但管理页面能打开。帮我查清楚原因，验证以后再给结论。</div></div><div class="message"><div class="message-role"><span class="ai-mark">${icon('spark',12)}</span>平台助手 <span style="font-size:8px;color:#a4afb4;font-weight:400"></span></div><p>已把管理访问和业务访问分开检查。当前合成观察是：</p><p>管理接口 <b>200</b>，业务入口 <b>502</b>，后端直连 <b>200</b>。</p><p>我会先核对转发配置，再检查请求是否到达后端。现在还不能把候选原因当作已验证结论。</p><button class="citation" data-detail="script">${icon('file',12)} 网络探测 · 3 个独立观察 ${icon('arrow',10)}</button><button class="citation" data-detail="model">${icon('book',12)} 查看本次分析的输入输出 ${icon('arrow',10)}</button><div class="reasoning-note">确定可核验的内容交给脚本。<br>需要理解与推断的内容由 LLM 判定。</div></div>${state.extraMessages.map(m=>`<div class="message">${m.role==='user'?`<div class="user-message">${esc(m.text)}</div>`:`<div class="message-role"><span class="ai-mark">${icon('spark',12)}</span>平台助手 · 模拟回答</div><p>${esc(m.text)}</p><button class="citation" data-detail="model">${icon('file',12)} 展开实际演示输入输出</button>`}</div>`).join('')}`:`<div class="message"><div class="info-banner">当前角色没有业务资料和任务内容的读取权限。管理平台不自动授予全部数据访问权。</div></div>`}</div><div class="quick-questions"><button class="quick-question" data-question="为什么管理可达不代表业务正常？">解释当前证据</button><button class="quick-question" data-question="还缺哪些证据才能确定原因？">还缺什么证据？</button></div><div class="composer"><textarea id="chat-input" aria-label="输入任务目标或问题" placeholder="提出目标、补充现象，或询问下一步…" ${!permitted?'disabled':''}></textarea><div class="composer-footer"><span>${icon('file',12)} 已关联任务、版本和证据</span><button class="send" data-action="send" aria-label="发送消息" ${!permitted?'disabled':''}>${icon('arrow',15)}</button></div></div><div class="chat-note">本 demo 不调用模型 · 输入仅在当前页面内存中</div></aside>`;}
const demoTasks=[{id:'TASK-0248',title:'修复升级后的连接异常，完成回归测试',scope:'ADC / 开发修复',status:'调查中',type:'green'},{id:'TASK-0247',title:'评审应用防护方案',scope:'WAF / 方案评审',status:'待复核',type:'amber'},{id:'TASK-0246',title:'准备会话保持的测试环境和用例',scope:'ADC / 测试',status:'调查中',type:'green'},{id:'TASK-0245',title:'检查发布版本的兼容性和回退记录',scope:'NGFW / 发布',status:'待复核',type:'amber'}];
function tasks(){return`${pageTitle('任务中心','查看进度，继续处理未完成的任务。',btn('new-task','新建任务',true,'plus'))}<div class="toolbar"><input class="search" id="task-search" value="${esc(state.taskFilter)}" placeholder="搜索任务名称或编号" aria-label="搜索演示"><select class="filter" id="task-status" aria-label="筛选任务状态"><option value="all">全部状态</option><option value="调查中">调查中</option><option value="待复核">待复核</option><option value="已交付">已交付</option></select></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>任务与目标</th><th>产品与环境</th><th>状态</th><th></th></tr></thead><tbody id="task-rows">${taskRows()}</tbody></table></div></div><div class="info-banner">任务列表为合成样例。新建任务在当前页面内存中保存，刷新后恢复演示初始状态。</div>`;}
function taskRows(){const rows=demoTasks.filter(t=>(t.title+t.id).toLowerCase().includes(state.taskFilter.toLowerCase())&&(state.taskStatus==='all'||t.status===state.taskStatus));return rows.map(t=>`<tr><td><span class="cell-main">${esc(t.id===state.taskId?state.title:t.title)}</span><span class="cell-sub">${t.id} · 项目内可追溯</span></td><td>${t.scope}</td><td>${tag(t.id===state.taskId&&state.complete?'已完成（模拟）':t.status,t.type)}</td><td><button class="btn small" data-action="search-task" data-task="${t.id}">打开 ${icon('arrow',10)}</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">没有匹配的演示</td></tr>';}
function environments(){return`${pageTitle('环境与拓扑','准备环境，查看拓扑和连接状态。',btn('environment','查看环境清单',false,'network'))}<div class="panel"><div class="panel-heading"><h2>${icon('network',14)} 负载均衡隔离网络</h2>${tag('合成 / rev.12','green')}</div><div class="tab-content">${businessPath()}</div></div><div class="panel"><div class="panel-heading"><h2>从物理层到应用层</h2><small>范围与缺项必须分别说明</small></div><div class="table-wrap"><table><thead><tr><th>调查范围</th><th>本环境能够观察</th><th>仍未覆盖</th></tr></thead><tbody><tr><td>物理 / 二层</td><td>拓扑声明与链路关系</td><td>${tag('未验证')} 真实介质、交换行为</td></tr><tr><td>三层 / 传输</td><td>合成路径、SSH、HTTP 连接</td><td>${tag('未验证')} 实际路由、回程、丢包</td></tr><tr><td>TLS / 应用</td><td>合成 HTTP 状态与转发目标</td><td>${tag('未验证')} TLS/SNI、真实业务</td></tr><tr><td>产品内部</td><td>合成身份、配置及方法版本</td><td>${tag('未验证')} 真实产品内部模块</td></tr></tbody></table></div></div>`;}
function knowledge(){return`${pageTitle('资料与记录','查看产品资料和任务记录。',btn('import','导入资料',false,'plus'))}<div class="panel"><div class="panel-heading"><h2>当前任务的依据</h2><small>项目范围：测试环境</small></div><div class="table-wrap"><table><thead><tr><th>内容</th><th>类型</th><th>修订</th><th></th></tr></thead><tbody>${[['model','转发配置的预期与适用条件','产品规范','rev.3'],['script','管理、业务与后端独立探测','现场观察 / 合成','run.0248'],['model','候选原因与证据缺口','模型判断 / 模拟','assessment.1'],['run','输入、过程与最终交付','任务记录 / 合成','run.0248']].map(([id,title,type,rev])=>`<tr><td><span class="cell-main">${title}</span><span class="cell-sub">产品与版本已绑定 · 原件可追查</span></td><td>${type}</td><td>${tag(rev)}</td><td><button class="btn small" data-detail="${id}">查看</button></td></tr>`).join('')}</tbody></table></div></div><div class="info-banner">维护包括导入失败处理、资料撤回、索引重建和备份恢复。发布或撤回不能改写已有任务使用的资料快照。</div>`;}
function execution(){const detail=can('read');return`${pageTitle('设备与执行','查看执行节点、设备连接和浏览器。',btn('health','检查健康状态',false,'check'))}<div class="resource-grid">${[['terminal','网络 worker','lab-network-01','SSH 跳转 / 合成设备','2 级跳转 · 测试域'],['globe','浏览器 worker','lab-browser-01','页面观察 / 演示会话','独立上下文 · 测试域'],['server','进程 worker','lab-process-01','本地合成工作区','取消与残留核对'],['network','任务运行服务','lab-task-runner','持久任务 / 设计基线','运行状态与执行状态分别查询']].map(([symbol,title,id,sub,foot])=>`<div class="resource-card"><div class="resource-top"><span class="row-icon">${icon(symbol,16)}</span>${tag('演示在线','green')}</div><h3>${title}</h3><p>${id}<br>${sub}</p><div class="resource-footer"><span class="subtle" style="font-size:9px;flex:1">${foot}</span><button class="btn small" ${detail?'data-detail="run"':'data-action="health"'}>观察</button></div></div>`).join('')}</div><div class="panel spacer"><div class="panel-heading"><h2>维护与控制</h2><small>当前角色：${roleNames[state.role].split(' · ')[0]}</small></div><div class="wide-message"><div class="toolbar">${btn('takeover','请求会话控制',false,'terminal')}${btn('maintenance','排空演示 worker',false,'server')}${btn('reconcile','核对远端结果',false,'check')}</div>连接断开不代表远端停止；取消请求、停止送达和实际停止确认分别记录。运维权限与设备业务操作权限分开。</div></div>`;}
function methods(){return`${pageTitle('方法库','查看、测试和发布操作方法。',btn('publish','发布方法版本',true,'code'))}<div class="panel"><div class="table-wrap"><table><thead><tr><th>方法</th><th>适用范围</th><th>判断方式</th><th>状态</th><th></th></tr></thead><tbody><tr><td><span class="cell-main">业务转发路径调查</span><span class="cell-sub">network-path-diagnosis / 1.2</span></td><td>合成负载均衡 v1</td><td>脚本探测 + LLM 原因分析</td><td>${tag('演示版本','green')}</td><td><button class="btn small" data-detail="method">查看</button></td></tr><tr><td><span class="cell-main">配置回读与差异比较</span><span class="cell-sub">configuration-reconcile / 1.0</span></td><td>声明的配置格式与规则</td><td>脚本确定规则</td><td>${tag('演示版本','green')}</td><td><button class="btn small" data-detail="script">查看</button></td></tr><tr><td><span class="cell-main">TLS/SNI 跨层排查</span><span class="cell-sub">tls-diagnosis / draft</span></td><td>尚未固定真实产品版本</td><td>证据采集 + LLM 分析</td><td>${tag('未验证','amber')}</td><td><button class="btn small" data-detail="method">查看</button></td></tr></tbody></table></div><div class="policy-note">运行中的任务固定方法版本；发布新版本不会替换旧任务。晋级与停用需要独立的测试和授权，不能把一次成功轨迹直接当通用规则。</div></div>`;}
function access(){return`${pageTitle('人员与权限','管理成员及其操作权限。',btn('policy','编辑演示策略',false,'shield'))}<div class="compact-summary"><span>${icon('shield',14)} 研发项目 / 测试环境 / LAB-* 资源</span>${tag('默认拒绝 · 策略 rev.4','green')}</div><div class="panel"><div class="panel-heading"><h2>人员角色与职责</h2><small>权限矩阵为设计示例</small></div><div class="table-wrap"><table><thead><tr><th>角色</th><th>业务查看</th><th>测试执行</th><th>方法发布</th><th>安全策略</th><th>平台维护</th></tr></thead><tbody>${Object.entries(roleNames).map(([r,title])=>`<tr><td><span class="cell-main">${title.split(' · ')[0]}</span></td>${['read','run','publish','policy','maintenance'].map(p=>`<td>${roles[r as Role].includes(p)?'<span style="color:#308f76">允许</span>':'<span style="color:#aab4b9">—</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="panel"><div class="panel-heading"><h2>实际操作前还要检查</h2>${icon('lock',14)}</div><div class="wide-message">已认证人员 → 项目成员 → 环境与目标 → 允许动作 → 有效委托 → 执行出口复核。<br><br>测试权限不包含生产操作；能查看会话不表示能控制会话。安全管理员维护策略，平台运维维护服务，都不会自动获得业务资料、设备凭据或生产变更权限。</div><div class="policy-note">本 demo 仅模拟权限反馈。正式鉴权必须在服务端与真实执行端强制检查；口令、MFA 与连接密钥不进入聊天、模型上下文或普通审计日志。</div></div>`;}
function audits(){const visible=can('read')||can('audit')||can('policy');return`${pageTitle('操作记录','查看操作人、操作时间和处理结果。')}<div class="panel"><div class="panel-heading"><h2>本页演示操作</h2>${tag('当前浏览器内存')}</div>${visible?(state.audits.length?state.audits.map(text=>`<div class="list-row"><span class="row-icon">${icon('audit',14)}</span><div class="row-main"><strong>${esc(text)}</strong><small>合成项目 · 演示策略 · 未产生真实设备作用</small></div></div>`).join(''):'<div class="empty">切换角色、运行演示或尝试受限操作后，记录会出现在这里。</div>'):'<div class="empty">没有查看审计的权限。</div>'}</div><div class="info-banner">正式审计需要可信身份、任务与操作关联、输入输出引用和保留策略。此处不是不可篡改的审计实现。</div>`;}
const evidence:Record<string,{title:string,kind:string,input:unknown,output:unknown,note:string}>={script:{title:'网络探测：实际输入输出样例',kind:'脚本 / 合成观察',input:{task:'TASK-0248',run:'DEMO-RUN-0248',target:'LAB-LB-01',environment:'isolated-fixture',method:'independent-probes@1.0',observations:['management','business-frontend','direct-backend'],expected:'Business forwarding returns 200'},output:{management:{httpStatus:200},businessFrontend:{httpStatus:502},directBackend:{httpStatus:200},scope:'Synthetic sample, not a live probe'},note:'脚本只能在明确输入和规则下核对结果。管理可达、前端异常、后端直连正常分别记录；本例不推导所有 502 的原因。'},model:{title:'原因分析：完整输入输出样例',kind:'LLM / 模拟返回',input:{model:'mock-only / no API call',method:'network-path-diagnosis@1.2',instruction:'Compare observations, propose causes and missing evidence; do not claim verified root cause.',product:'synthetic-load-balancer@fixture-v1',evidence:['management=200','business=502','direct-backend=200'],specification:'The virtual service should forward to demo-backend',messages:[]},output:{judgment:'Forwarding configuration mismatch is a candidate cause',support:['Management and business have different outcomes','Backend direct observation was normal'],missing:['Read actual virtual-service target','Correlate frontend request with backend arrival'],verifiedRootCause:false},note:'这是固定的模拟回答。真实平台应披露实际发送的上下文、消息、证据与实际返回内容，说明摘要或遮蔽范围。模型置信度不代替事实。'},run:{title:'任务、执行与交付记录',kind:'任务与操作 / 演示',input:{task:'TASK-0248',inputRevision:1,knowledgeSnapshot:'demo-knowledge-rev3',method:'network-path-diagnosis@1.2',environmentRevision:12,allowedScope:'isolated-test-only'},output:{accepted:'demo',execution:'simulated',businessVerification:'synthetic-only',delivery:'not a real product acceptance',unknowns:['Real product behavior','Physical topology','Real model diagnostic quality']},note:'任务状态、实际执行、业务验证和交付分别确认。通知、模型文字与 UI 动画不能作为真实效果证据。'},method:{title:'方法库与版本边界',kind:'专业方法 / 示例',input:{id:'network-path-diagnosis',version:'1.2',product:'synthetic-load-balancer',preconditions:['Known topology and expected behavior','Independent observation points','Authorized test environment']},output:{scriptResponsibilities:['Read explicit configuration','Collect probes and logs','Compare against fixed expectations'],modelResponsibilities:['Interpret cross-layer evidence','Evaluate candidate causes','Choose discriminating next check'],promotion:'Requires independent validation and release permission'},note:'旧任务固定旧方法；改进可以形成新版本，不能悄悄修改历史结论。'} };
function openDetail(id:string){rememberFocus();if(!allowed('read'))return;let item=evidence[id];if(!item){const titles:Record<string,string>={client:'客户端观察点',network:'网络路径与层级',device:'产品与实际配置',backend:'后端独立观察点'};item={title:titles[id]??'合成环境',kind:'拓扑 / 合成内容',input:{target:id,environment:'isolated-fixture',task:state.taskId},output:{observation:id==='device'?(state.complete?'200 / simulated':'502 / synthetic'):id==='backend'?'200 / synthetic':'Declared synthetic path',scope:'No physical network observation'},note:'点击路径节点用于关联配置、日志和流量观察。此 demo 没有真实网络或物理层证据。'};}if(state.missionKind!=='diagnosis'&&state.missionKind!=='operate'&&id==='script'){item={title:'明确规则的核验：输入输出样例',kind:'脚本 / 合成记录',input:{task:state.taskId,product:state.product,sourceRevision:'synthetic-rev3',rule:'Verify source reference and input binding',scope:'Demo only'},output:{referenceExists:true,inputBinding:'synthetic-current',proves:'The explicit synthetic reference and binding match',doesNotProve:'Semantic judgment or actual product outcome'},note:'脚本按照明确规则核对输入与引用；通过不表示语义结论正确。本例为合成内容。'};}if(id==='run'){item={...item,input:{...(item.input as any),task:state.taskId,goal:state.title,product:state.product,method:state.missionKind}};}const input=structuredClone(item.input) as any;if(id==='model'){input.messages=state.extraMessages;input.product=state.product;input.goal=state.title;if(state.missionKind!=='diagnosis'){input.method=`${state.missionKind}-workflow / mock-only`;input.evidence=['Synthetic specification revision','Synthetic code context','Synthetic test environment'];input.specification='Deliver the goal with independently verified outputs';item={...item,output:{reply:'Combine product knowledge, code, environment and verification into the current task',scope:'Mock response only',steps:missionKinds[state.missionKind]?.steps,unverified:['Real model judgment','Real product outcome']}};}}document.body.insertAdjacentHTML('beforeend',`<div class="drawer-backdrop" data-action="close-overlay"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="${item.title}"><div class="drawer-title"><div><div class="eyebrow">INPUT / OUTPUT</div><h2>${item.title}</h2>${tag(item.kind,'blue')}</div><button class="close" data-action="close-overlay" aria-label="关闭详情">×</button></div><p>${item.note}</p><div class="data-block"><h3>实际输入样例 · 当前修订</h3><pre>${esc(JSON.stringify(input,null,2))}</pre></div><div class="data-block"><h3>原始输出样例 · 未省略字段</h3><pre>${esc(JSON.stringify(item.output,null,2))}</pre></div><div class="info-banner">只包含合成内容，不含业务资料或凭据。真实平台须按项目权限提供原件及来源、版本、运行、目标和时间绑定。</div><div style="margin-top:20px">${btn('download','下载此演示记录',false,'file')}</div></aside>`);(document.querySelector('.drawer .close') as HTMLButtonElement)?.focus();}
let lastFocused:Element|null=null;
function rememberFocus(){lastFocused=document.activeElement;}
function closeOverlay(){document.querySelectorAll('.drawer,.drawer-backdrop,.modal,.modal-backdrop').forEach(e=>e.remove());if(lastFocused?.isConnected)(lastFocused as HTMLElement).focus();}
function newTask(){rememberFocus();if(!allowed('create'))return;document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-action="close-overlay"></div><div class="modal" role="dialog" aria-modal="true" aria-label="新建演示"><div class="drawer-title"><h2>把目标交给平台</h2><button class="close" data-action="close-overlay" aria-label="关闭新建任务">×</button></div><label for="new-goal">希望完成什么</label><textarea id="new-goal" placeholder="描述目标、出现的现象和期望结果"></textarea><label for="new-product">产品与环境</label><select id="new-product"><option>合成负载均衡 v1 / 测试环境网络</option></select><div class="info-banner">当前授权只覆盖演示项目；新任务不会连接设备、运行脚本或调用模型。</div><div class="modal-actions">${btn('close-overlay','取消')}${btn('create-task','创建演示',true,'arrow')}</div></div>`);(document.querySelector('#new-goal') as HTMLTextAreaElement).focus();}
function sendMessage(text?:string){if(!allowed('read'))return;const input=document.querySelector('#chat-input') as HTMLTextAreaElement;const message=text??input.value.trim();if(!message){notice('请输入目标或问题。');return;}const response=state.missionKind!=='diagnosis'?'收到。我会按你补充的内容调整后续步骤，保留此前的记录。':message.includes('缺')?'还需回读实际转发目标，并关联前端请求与后端到达记录。现有证据支持调查转发路径，不能证明具体路由或产品模块有缺陷。':message.includes('管理')?'管理接口和业务转发是不同路径。管理 200 只能说明该次管理请求成功；需要独立检查前端、后端和实际转发配置。':'已把你的输入关联到当前演示。完整产品会根据新输入检查计划与旧结论是否仍适用；本 demo 仅展示这一交互，不实际调用模型或执行操作。';state.chatDraft='';state.extraMessages.push({role:'user',text:message},{role:'assistant',text:response});audit('提交 Web 对话输入 / 模拟回答');render();const messages=document.querySelector('.chat-messages');if(messages)messages.scrollTop=messages.scrollHeight;}
function stepRun(){if(!state.running)return;state.phase++;if(state.phase>=6){state.running=false;state.complete=true;state.phase=6;audit('演示完成：模拟修复、回归与交付');notice('诊断演示完成。没有真实设备或模型调用。');render();return;}audit(`演示步骤推进至 ${state.phase+1}`);render();runTimer=setTimeout(stepRun,1100);}
function startRun(){if(!allowed('run'))return;if(state.running)return;if(state.complete){state.complete=false;state.phase=3;}state.paused=false;state.running=true;audit('开始诊断演示 / 测试域');render();runTimer=setTimeout(stepRun,1000);}
document.addEventListener('click',event=>{const target=(event.target as HTMLElement).closest<HTMLElement>('[data-view],[data-tab],[data-workspace-tab],[data-action],[data-detail],[data-question]');if(!target)return;if(target.dataset.view){closeOverlay();navigate(target.dataset.view as View);return;}if(target.dataset.tab){state.tab=target.dataset.tab;render();return;}if(target.dataset.workspaceTab){state.workspaceTab=target.dataset.workspaceTab;render();return;}if(target.dataset.detail){openDetail(target.dataset.detail);return;}if(target.dataset.question){sendMessage(target.dataset.question);return;}switch(target.dataset.action){case'search-task':{const task=demoTasks.find(t=>t.id===target.dataset.task);if(task){state.product=task.scope.startsWith('WAF')?'WAF 应用安全':task.scope.startsWith('NGFW')?'NGFW 网络安全':'ADC 应用交付';closeOverlay();launchMission(task.title,undefined,false);state.taskId=task.id;render();}break;}case'demo-info':showDemoInfo();break;case'search':openSearch();break;case'diagram-step':openStep(Number(target.dataset.step));break;case'chat-toggle':state.chatOpen=!state.chatOpen;render();break;case'close-overlay':closeOverlay();break;case'new-task':newTask();break;case'create-task':{if(!allowed('create'))break;const goal=(document.querySelector('#new-goal') as HTMLTextAreaElement).value.trim();if(!goal){notice('请填写任务目标。');break;}if(runTimer)clearTimeout(runTimer);state.running=false;state.paused=false;state.extraMessages=[];state.startDraft='';state.chatDraft='';state.title=goal;state.taskId=`TASK-${String(248+demoTasks.length-2).padStart(4,'0')}`;demoTasks.unshift({id:state.taskId,title:goal,scope:'合成负载均衡 / 测试域',status:'调查中',type:'green'});state.complete=false;state.phase=0;state.view='workbench';closeOverlay();audit('创建演示');render();notice('已创建演示，内容仅保存在当前页面。');break;}case'send':sendMessage();break;case'launch-goal':{const goal=(document.querySelector('#start-goal') as HTMLTextAreaElement).value.trim();if(!goal){notice('请填写你希望完成的目标。');break;}launchMission(goal);break;}case'preset':launchMission(target.dataset.goal!,target.dataset.kind);break;case'open-mission':if(target.dataset.product)state.product=target.dataset.product;launchMission(target.dataset.goal!,target.dataset.kind,false);break;case'choose-product':state.product=target.dataset.product!;render();notice(`已切换到 ${state.product} 的演示产品空间`);break;case'run':startRun();break;case'pause':if(allowed('run')){if(runTimer)clearTimeout(runTimer);state.running=false;state.paused=true;audit('暂停 / 不代表真实远端停止');render();}break;case'takeover':if(allowed('control')){audit('模拟请求会话控制');notice('已模拟请求控制。真实平台必须核验控制授权与在途操作。');}break;case'publish':if(allowed('publish')){audit('模拟提交方法发布请求');notice('方法发布请求已演示；没有修改真实方法或发布版本。');}break;case'policy':if(allowed('policy')){audit('模拟编辑策略');notice('演示策略已打开；本 demo 不修改真实权限。');}break;case'maintenance':if(allowed('maintenance')){audit('模拟排空 worker');notice('已模拟排空请求；没有实际进程被停止。');}break;case'health':audit('查询演示健康状态');notice('所有状态均为合成展示，未探测真实服务。');break;case'reconcile':if(allowed('run'))openDetail('run');break;case'import':if(allowed('create'))notice('导入流程示意：固定原件、版本与权限后，再解析和建立索引。');break;case'environment':openDetail('network');break;case'download':{const data=JSON.stringify({scope:'synthetic-demo-only',task:state.taskId,role:state.role,modelCalled:false,evidence,state},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='infosec-demo-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}});
document.addEventListener('change',event=>{const target=event.target as HTMLSelectElement;if(target.id==='role'){if(runTimer)clearTimeout(runTimer);state.running=false;state.role=target.value as Role;audit('切换演示角色');render();}if(target.id==='home-product'){state.product=target.value;}if(target.id==='task-status'){state.taskStatus=target.value;document.querySelector('#task-rows')!.innerHTML=taskRows();}});
document.addEventListener('input',event=>{const target=event.target as HTMLInputElement;if(target.id==='global-query')updateSearch(target.value);if(target.id==='start-goal')state.startDraft=target.value;if(target.id==='chat-input')state.chatDraft=target.value;if(target.id==='task-search'){state.taskFilter=target.value;document.querySelector('#task-rows')!.innerHTML=taskRows();}});
document.addEventListener('keydown',event=>{if(event.key==='Tab'){const dialog=document.querySelector('[role=dialog]');if(dialog){const focusable=Array.from(dialog.querySelectorAll<HTMLElement>('button:not([disabled]),input,textarea,select,[tabindex="0"]'));const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}}if((event.key==='Enter'||event.key===' ')&&(event.target as HTMLElement).dataset.step){event.preventDefault();openStep(Number((event.target as HTMLElement).dataset.step));}if(event.key==='Escape')closeOverlay();if(event.key.toLowerCase()==='k'&&(event.metaKey||event.ctrlKey)){event.preventDefault();openSearch();}if(event.key==='Enter'&&(event.metaKey||event.ctrlKey)&&(event.target as HTMLElement).id==='chat-input'){event.preventDefault();sendMessage();}});
render();

window.addEventListener('popstate',()=>{const view=location.hash.slice(2) as View;if(nav.some(n=>n[0]===view)){state.view=view;render();}});
